-- legal_search_mock food_safety_2026 — init.sql
-- A synthesized 食品安全/网络购物 consumer-punitive-damages dispute research corpus for a 打官司 benchmark:
--   • 6 courts across 上海/浙江 (含网购收货地上海浦东法院 + 卖家所在地杭州法院 + 电商平台所在地)
--   • 4 statutes: 食品安全法 + 消费者权益保护法 + 民法典 + 最高法食品药品纠纷司法解释
--   • 18 anonymized 食品安全/网购合同 judgments (退一赔十/价款十倍or损失三倍/1000元保底/
--     知假买假食品领域仍赔/进口食品无中文标签/超过保质期/非法添加/标签瑕疵不赔/生产者销售者择一/
--     平台连带or先行赔付/网购管辖收货地 ...)
--   • citation links from cases → statute articles (and a few case→case references)
--   • seeded user usr_zhao_meng with 2 saved cases + notes (preparing a 食品安全惩罚性赔偿诉讼)
-- All party names anonymized (张某/某公司). All text original/synthesized; statute text
-- simplified public-domain-style. Reference date: 2026-05-20 (scenario reference; server has no clock).

BEGIN;

-- ── Courts / 法院 ───────────────────────────────────────────────────

-- ── Statutes ───────────────────────────────────────────────────────
    '规范食品生产经营、标签标识、进口食品要求与法律责任。第一百四十八条规定生产不符合食品安全标准的食品或经营明知不符合食品安全标准的食品的，消费者除要求赔偿损失外，可向生产者或经营者要求支付价款十倍或损失三倍的惩罚性赔偿，增加赔偿金额不足一千元的按一千元计；但食品标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的除外。'),
  ('stat_cpl_consumer', '中华人民共和国消费者权益保护法', '消费者权益保护法', '全国人民代表大会常务委员会', '2014-03-15', '现行有效',
    '保护消费者合法权益。第五十五条规定经营者提供商品或服务有欺诈行为的，应按消费者购买价款的三倍增加赔偿，增加赔偿不足五百元的为五百元(普通消费品三倍赔偿)；电子商务平台经营者的相关责任亦有规定。'),
  ('stat_ccl',  '中华人民共和国民法典', '民法典', '全国人民代表大会', '2021-01-01', '现行有效',
    '规范民事主体的人身关系和财产关系，含合同编(买卖合同、违约责任)、侵权责任编(产品责任、生产者销售者责任、惩罚性赔偿)以及总则编(三年诉讼时效)等核心条款。'),
  ('stat_interp','最高人民法院关于审理食品药品纠纷案件适用法律若干问题的规定', '食药纠纷规定', '最高人民法院', '2021-01-01', '现行有效',
    '明确食品药品纠纷审理规则：购买者明知食品不符合安全标准仍购买并主张惩罚性赔偿的，人民法院不予支持其请求的抗辩在食品、药品领域不成立(即"知假买假"在食药领域不影响索赔)；网络交易平台的责任、生产者与销售者的赔偿责任竞合等。');

-- ── Statute articles (法条) ─────────────────────────────────────────
-- 食品安全法 key articles
    '消费者因不符合食品安全标准的食品受到损害的，可以向经营者或者生产者要求赔偿损失。生产不符合食品安全标准的食品或者经营明知是不符合食品安全标准的食品，消费者除要求赔偿损失外，还可以向生产者或者经营者要求支付价款十倍或者损失三倍的赔偿金；增加赔偿的金额不足一千元的，为一千元。但是，食品的标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的除外。'),
  ('art_fsl_097', 'stat_fsl', '第九十七条', 97, '进口预包装食品中文标签',
    '进口的预包装食品、食品添加剂应当有中文标签；依法应当有说明书的，还应当有中文说明书。标签、说明书应当符合本法以及我国其他有关法律、行政法规的规定和食品安全国家标准的要求，并载明食品的原产地以及境内代理商的名称、地址、联系方式。预包装食品没有中文标签、中文说明书或者标签、说明书不符合本条规定的，不得进口。'),
  ('art_fsl_034', 'stat_fsl', '第三十四条', 34, '禁止生产经营的食品(超过保质期/非法添加等)',
    '禁止生产经营下列食品：用非食品原料生产的食品或者添加食品添加剂以外的化学物质和其他可能危害人体健康物质的食品；超过保质期的食品；标注虚假生产日期、保质期或者超过保质期的食品；无标签的预包装食品；以及其他不符合食品安全标准或者要求的食品。'),
  ('art_fsl_150', 'stat_fsl', '第一百五十条', 150, '食品安全与食品安全标准的含义',
    '食品安全，指食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或者慢性危害。食品安全标准是强制执行的标准。');

-- 消费者权益保护法 key articles
    '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务费用的三倍；增加赔偿的金额不足五百元的，为五百元。注：食品安全领域的惩罚性赔偿优先适用食品安全法第一百四十八条(十倍/保底一千元)，与本条三倍/五百元不同。'),
  ('art_cpl_c_44', 'stat_cpl_consumer', '第四十四条', 44, '网络交易平台责任',
    '消费者通过网络交易平台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿。网络交易平台提供者不能提供销售者或者服务者的真实名称、地址和有效联系方式的，消费者也可以向网络交易平台提供者要求赔偿；网络交易平台提供者作出更有利于消费者承诺的，应当履行承诺。平台明知或者应知销售者侵害消费者合法权益未采取必要措施的，依法与销售者承担连带责任。');

-- 民法典 key articles
    '向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。'),
  ('art_ccl_1203', 'stat_ccl', '第一千二百零三条', 1203, '产品责任(生产者销售者赔偿竞合)',
    '因产品存在缺陷造成他人损害的，被侵权人可以向产品的生产者请求赔偿，也可以向产品的销售者请求赔偿。产品缺陷由生产者造成的，销售者赔偿后，有权向生产者追偿；因销售者的过错使产品存在缺陷的，生产者赔偿后，有权向销售者追偿。'),
  ('art_ccl_509', 'stat_ccl', '第五百零九条', 509, '合同履行原则',
    '当事人应当按照约定全面履行自己的义务。当事人应当遵循诚信原则，根据合同的性质、目的和交易习惯履行通知、协助、保密等义务。');

-- 最高法食药纠纷规定 key articles
    '因食品、药品质量问题发生纠纷，购买者向生产者、销售者主张权利，生产者、销售者以购买者明知食品、药品存在质量问题而仍然购买为由进行抗辩的，人民法院不予支持。即在食品、药品领域，购买者是否"知假买假"不影响其依法主张惩罚性赔偿。'),
  ('art_interp_06', 'stat_interp', '第六条', 6, '网络交易平台先行赔付与连带责任',
    '消费者通过网络交易平台购买食品、药品，其合法权益受到损害，网络交易平台提供者不能提供生产者或者销售者的真实名称、地址和有效联系方式的，消费者请求网络交易平台提供者承担赔偿责任的，人民法院应予支持。网络交易平台提供者承担赔偿责任后，有权向生产者或者销售者追偿。平台明知或应知销售者利用平台侵害消费者权益未采取必要措施的，与销售者承担连带责任。'),
  ('art_interp_15', 'stat_interp', '第十五条', 15, '不影响安全且无误导的标签瑕疵除外',
    '生产经营的食品符合食品安全标准，但其标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵，消费者请求支付价款十倍惩罚性赔偿金的，人民法院不予支持。即仅有不影响食品安全、不误导的标签瑕疵，不适用十倍惩罚性赔偿。');

